ALTER POLICY vibz_create ON public.vibz_posts WITH CHECK (creator_id = auth.uid() AND status = 'pending' AND likes_count = 0 AND comments_count = 0 AND shares_count = 0 AND length(media_path) < 240 AND media_path ~ ('^' || auth.uid()::text || '/[a-zA-Z0-9-]+[.](mp4|mov|webm|m4v|3gp|ogv)$') AND EXISTS (SELECT 1 FROM public._profile_guard(auth.uid()) p WHERE p.account_status = 'active' AND NOT p.is_suspended));
ALTER POLICY vibein_add ON public.vibein WITH CHECK (follower_id = auth.uid() AND EXISTS (SELECT 1 FROM public._profile_guard(creator_id) p WHERE p.account_status = 'active' AND NOT p.is_suspended));
ALTER POLICY vibz_media_insert ON storage.objects WITH CHECK (bucket_id = 'vibz-media' AND owner_id = auth.uid()::text AND (storage.foldername(name))[1] = auth.uid()::text AND name ~ ('^' || auth.uid()::text || '/[a-zA-Z0-9-]+[.](mp4|mov|webm|m4v|3gp|ogv)$'));